# Search for ARC-related files or directories
for root, dirs, files in os.walk('/home/USER'):
    # Stop at depth 4 to avoid going too deep
    if root.endswith('/workspace') or root.endswith('/runs') or root.endswith('/snapshots'):
        continue
    for f in files:
        if '/arc/' in root or 'arc_' in f.lower():
            print(root, f)

# Check if we can access the ARC API
import requests
import json

# Try to access the ARC API based on the environment variable
base_url = os.environ.get('ARC_LLM_BASE_URL', '')
print(f"ARC LLM Base URL: {base_url}")

# List the available API endpoints or check if we can access it
try:
    # Try some common endpoints
    endpoints_to_try = ['/v1/models', '/v1/completions', '/health']
    for ep in endpoints_to_try:
        try:
            resp = requests.get(base_url + ep, timeout=5)
            print(f"Endpoint {ep}: {resp.status_code}")
            if resp.status_code == 200:
                print(f"  Response: {resp.text[:500]}")
        except Exception as e:
            print(f"Endpoint {ep}: Error - {e}")
except Exception as e:
    print(f"Error: {e}")

