# Explore the arc-pa directory
import os
import glob

arc_dir = '/tmp/arc-pa-h1wsl94z'
print(f"Contents of {arc_dir}:")
for f in os.listdir(arc_dir):
    print(f"  {f}")

# Search for JSON files
for root, dirs, files in os.walk(arc_dir):
    for f in files:
        if f.endswith('.json'):
            path = os.path.join(root, f)
            print(f"JSON file: {path}")
            # Try to read it
            try:
                with open(path, 'r') as fp:
                    data = json.load(fp)
                    print(f"  Keys: {data.keys() if isinstance(data, dict) else type(data)}")
            except Exception as e:
                print(f"  Error: {e}")

